// Reads candidate openclaw.json on stdin, validates against the vendored zod
// schema bundle. Exit 0 = valid; exit 1 = invalid (zod issues printed to stderr).
//
// The bundle (openclaw-config-schema.mjs) is generated by
// scripts/vendor_openclaw_schema.sh. If it's absent, exit 2 so the caller can
// distinguish "schema not vendored" from "config invalid".
import { existsSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join, resolve } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const bundlePath = process.argv[2]
  ? resolve(process.argv[2])
  : join(here, "openclaw-config-schema.mjs");

if (!existsSync(bundlePath)) {
  console.error("schema bundle missing: run scripts/vendor_openclaw_schema.sh");
  process.exit(2);
}

const { ConfigSchema } = await import(pathToFileURL(bundlePath).href);

let raw = "";
process.stdin.on("data", (c) => (raw += c));
process.stdin.on("end", () => {
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    console.error("invalid JSON: " + e.message);
    process.exit(1);
  }
  const result = ConfigSchema.safeParse(parsed);
  if (result.success) {
    process.exit(0);
  }
  console.error(JSON.stringify(result.error.issues, null, 2));
  process.exit(1);
});
